// ---- v2.3.2: Pre-rendered asset cache ----
// Background PNGs (one per level theme) and unit icon PNGs are generated by
// gen_assets.py and live in the assets/ folder. They are loaded lazily and
// cached so the canvas can draw them via drawImage without re-decoding.
// The path is resolved relative to this script's location so it works under
// file://, http://, and GitHub Pages.
function assetBase() {
  try {
    const scripts = document.getElementsByTagName("script");
    const src = (scripts && scripts[scripts.length - 1] && scripts[scripts.length - 1].src) || "";
    if (src) return src.replace(/[^/\\]*$/, "assets/");
  } catch (e) {}
  return "assets/";
}
const ASSET_BASE = assetBase();
const bgImages = {};
const unitImages = {};
let pendingRedraw = false;
function scheduleRedraw() {
  if (pendingRedraw) return;
  pendingRedraw = true;
  if (typeof requestAnimationFrame === "function") {
    requestAnimationFrame(() => { pendingRedraw = false; if (typeof draw === "function") draw(); });
  } else if (typeof setTimeout === "function") {
    setTimeout(() => { pendingRedraw = false; if (typeof draw === "function") draw(); }, 50);
  }
}
function loadBg(theme) {
  if (bgImages[theme]) return bgImages[theme];
  if (typeof Image === "undefined") return null;
  const img = new Image();
  img.src = ASSET_BASE + "bg_" + theme + ".png";
  img.onload = scheduleRedraw;
  img.onerror = scheduleRedraw;
  bgImages[theme] = img;
  return img;
}
function loadUnit(kind) {
  if (unitImages[kind]) return unitImages[kind];
  if (typeof Image === "undefined") return null;
  const img = new Image();
  img.src = ASSET_BASE + kind + ".png";
  img.onload = scheduleRedraw;
  img.onerror = scheduleRedraw;
  unitImages[kind] = img;
  return img;
}

